package com.example.kyrgyzkeyboard.data.repository

import android.content.SharedPreferences
import androidx.core.content.edit
import com.example.kyrgyzkeyboard.data.model.KeyboardSettings

/**
 * 键盘设置仓库：基于 [SharedPreferences] 的键值持久化。
 *
 * 选用 SharedPreferences 而非 DataStore 是为了与已有依赖对齐；
 * 若后续切换到 DataStore，仅本类需要改动。
 */
class SettingsRepository(private val preferences: SharedPreferences) {

    /** 读取当前设置；缺省项走 [KeyboardSettings] 的默认值。 */
    suspend fun getSettings(): KeyboardSettings {
        val defaults = KeyboardSettings()
        return KeyboardSettings(
            vibrateEnabled = preferences.getBoolean(KEY_VIBRATE, defaults.vibrateEnabled),
            soundEnabled = preferences.getBoolean(KEY_SOUND, defaults.soundEnabled),
            theme = preferences.getString(KEY_THEME, defaults.theme) ?: defaults.theme,
            fontSize = preferences.getFloat(KEY_FONT_SIZE, defaults.fontSize),
            autoCorrection = preferences.getBoolean(KEY_AUTO_CORRECTION, defaults.autoCorrection),
            swipeGesture = preferences.getBoolean(KEY_SWIPE_GESTURE, defaults.swipeGesture),
            kyrgyzAssociation = preferences.getBoolean(KEY_KYRGYZ_ASSOCIATION, defaults.kyrgyzAssociation)
        )
    }

    /** 保存设置。 */
    suspend fun saveSettings(settings: KeyboardSettings) {
        preferences.edit {
            putBoolean(KEY_VIBRATE, settings.vibrateEnabled)
            putBoolean(KEY_SOUND, settings.soundEnabled)
            putString(KEY_THEME, settings.theme)
            putFloat(KEY_FONT_SIZE, settings.fontSize)
            putBoolean(KEY_AUTO_CORRECTION, settings.autoCorrection)
            putBoolean(KEY_SWIPE_GESTURE, settings.swipeGesture)
            putBoolean(KEY_KYRGYZ_ASSOCIATION, settings.kyrgyzAssociation)
        }
    }

    companion object {
        const val PREFS_NAME = "keyboard_settings"

        const val KEY_VIBRATE = "vibrate_enabled"
        const val KEY_SOUND = "sound_enabled"
        private const val KEY_THEME = "theme"
        const val KEY_FONT_SIZE = "font_size"
        private const val KEY_AUTO_CORRECTION = "auto_correction"
        private const val KEY_SWIPE_GESTURE = "swipe_gesture"
        const val KEY_KYRGYZ_ASSOCIATION = "kyrgyz_association"
    }
}